using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer.Tools;

[McpServerToolType]
public class ApiFetchTool
{
    private readonly IHttpClientFactory _httpClientFactory;

    public ApiFetchTool(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public async Task<string> FetchData(
        [Description("The relative API path to query, e.g. '/users/1'")] string path,
        CancellationToken cancellationToken)
    {
        using var client = _httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path.TrimStart('/'), cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using Microsoft.Extensions.AI;
using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer.Prompts;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired length: 'brief', 'detailed', or 'bullet-points'")] string style = "brief")
    {
        var instruction = style.ToLowerInvariant() switch
        {
            "detailed" => "Provide a detailed summary that captures all key points, arguments, and supporting details.",
            "bullet-points" => "Summarize the text as a concise list of bullet points.",
            _ => "Provide a brief, one-paragraph summary capturing only the main idea.",
        };

        return
        [
            new(ChatRole.User,
                $"""
                 Please summarize the following text.

                 Style: {instruction}

                 ---
                 {text}
                 ---
                 """),
        ];
    }
}

